"""Computer opponent with three difficulty levels."""

import random
import time

from pylonchess.board import PIECE_VALUES
from pylonchess.pieces import Color, PieceType

# Iterative deepening limits for the "hard" level.
HARD_MAX_DEPTH = 3
HARD_TIME_LIMIT = 2.0      # seconds per move
QUIESCENCE_MAX_DEPTH = 6   # extra capture plies explored after the search depth


def _move_order_value(board, move):
    """MVV-LVA ordering key: prefer capturing a valuable piece with a cheap one."""
    (fr, fc), (tr, tc) = move
    mover = board.get_piece(fr, fc)
    target = board.get_piece(tr, tc)
    attacker = PIECE_VALUES.get(mover.piece_type, 0) if mover else 0
    victim = PIECE_VALUES.get(target.piece_type, 0) if target \
        else PIECE_VALUES.get(PieceType.PAWN, 0)
    return -(10 * victim - attacker)


class ChessAI:
    """Difficulty: 'easy' (random), 'medium' (minimax depth 2),
    'hard' (iterative deepening + alpha-beta + quiescence)."""

    def __init__(self, difficulty="medium"):
        self.played_moves = []
        self.set_difficulty(difficulty)

    def reset(self):
        """Clear the AI's own move history (new game)."""
        self.played_moves = []

    def set_difficulty(self, difficulty):
        self.difficulty = difficulty
        if difficulty == "easy":
            self.depth = 1
        elif difficulty == "medium":
            self.depth = 2
        else:
            self.depth = 3

    def choose_move(self, board):
        """Return a ((from), (to)) move for the current player, or None."""
        moves = board.get_all_moves(board.current_turn)
        if not moves:
            return None

        repeat_move = self._repeated_move()

        if self.difficulty == "easy":
            # Prefer captures, otherwise random
            capturing = [m for m in moves if board.get_piece(m[1][0], m[1][1])]
            pool = capturing or moves
            if repeat_move is not None:
                pool = [m for m in pool if m != repeat_move] or moves
            move = random.choice(pool)
            self.played_moves.append(move)
            return move

        if self.difficulty == "hard":
            best_move = self._iterative_deepen(board)
        else:
            best_move, _ = self._search_root(board, self.depth)

        # If the AI has played the exact same move three times in a row, be
        # creative on the fourth and pick a different, still-solid move.
        if repeat_move is not None and best_move is not None:
            creative = self._creative_move(board, moves, repeat_move)
            if creative is not None:
                best_move = creative

        self.played_moves.append(best_move)

        return best_move

    def _iterative_deepen(self, board):
        """Search with increasing depth until the time budget runs out.
        Returns the best move found at the deepest completed search."""
        start = time.time()
        best_move = None
        for depth in range(1, HARD_MAX_DEPTH + 1):
            if time.time() - start >= HARD_TIME_LIMIT and depth > 1:
                break
            move, _ = self._search_root(board, depth)
            if move is not None:
                best_move = move
        return best_move

    def _search_root(self, board, depth):
        """Full-width negamax search at the root. Returns (best_move, score)."""
        moves = board.get_all_moves(board.current_turn)
        if not moves:
            return None, None

        sorted_moves = sorted(moves, key=lambda m: _move_order_value(board, m))
        alpha = float("-inf")
        best_move = None
        best_score = float("-inf")

        for move in sorted_moves:
            rec = board.simulate_move(move)
            score = -self._negamax(board, depth - 1, float("-inf"), -alpha)
            board.undo_simulation(rec)
            if score > best_score:
                best_score = score
                best_move = move
            if best_score > alpha:
                alpha = best_score

        return best_move, best_score

    def _repeated_move(self):
        """Return the move if it was played by the AI three times in a row,
        otherwise None."""
        if len(self.played_moves) >= 3 and self.played_moves[-1] == \
                self.played_moves[-2] == self.played_moves[-3]:
            return self.played_moves[-1]
        return None

    def _creative_move(self, board, moves, repeated):
        """Score every legal move except the repeated one and return a random
        near-best alternative (a 'creative' response)."""
        scored = []
        for move in moves:
            if move == repeated:
                continue
            rec = board.simulate_move(move)
            score = -self._negamax(board, self.depth - 1, float("-inf"), float("inf"))
            board.undo_simulation(rec)
            scored.append((score, move))
        if not scored:
            return None
        best = max(s for s, _ in scored)
        # Within roughly a pawn of the best option, choose freely.
        near_best = [m for s, m in scored if s >= best - 80]
        return random.choice(near_best)

    def _negamax(self, board, depth, alpha, beta):
        """Returns score from perspective of player to move."""
        moves = board.get_all_moves(board.current_turn)
        if not moves:
            # checkmate or stalemate
            if board.is_in_check(board.current_turn):
                return -20000 + (self.depth - depth) * 10  # prefer faster mates
            return 0

        if depth <= 0:
            return self._quiescence(board, alpha, beta)

        sorted_moves = sorted(moves, key=lambda m: _move_order_value(board, m))

        best = float("-inf")
        for move in sorted_moves:
            rec = board.simulate_move(move)
            score = -self._negamax(board, depth - 1, -beta, -alpha)
            board.undo_simulation(rec)
            if score > best:
                best = score
            if best > alpha:
                alpha = best
            if alpha >= beta:
                break
        return best if best != float("-inf") else self._quiescence(board, alpha, beta)

    def _quiescence(self, board, alpha, beta, qdepth=QUIESCENCE_MAX_DEPTH):
        """Extend the search with capture moves only (incl. en passant) to
        avoid the horizon effect at the leaf of the main search."""
        stand_pat = board.evaluate()
        if stand_pat >= beta:
            return beta
        if stand_pat > alpha:
            alpha = stand_pat
        if qdepth <= 0:
            return alpha

        captures = [m for m in board.get_all_moves(board.current_turn)
                    if self._is_capture(board, m)]
        if not captures:
            return alpha
        captures.sort(key=lambda m: _move_order_value(board, m))

        for move in captures:
            rec = board.simulate_move(move)
            score = -self._quiescence(board, -beta, -alpha, qdepth - 1)
            board.undo_simulation(rec)
            if score >= beta:
                return beta
            if score > alpha:
                alpha = score
        return alpha

    @staticmethod
    def _is_capture(board, move):
        """True if the move wins material: a normal capture or en passant."""
        (fr, fc), (tr, tc) = move
        if board.get_piece(tr, tc) is not None:
            return True
        piece = board.get_piece(fr, fc)
        return bool(piece and piece.piece_type == PieceType.PAWN and
                    board.en_passant_target == (tr, tc))